export const LETTER_PREVIEWS = Object.freeze(Object.fromEntries(Object.entries(PREVIEWS).map(([id, value]) => [id, Object.freeze(value)])));
export const LETTER_SETS = Object.freeze(CATALOGUE.map(entry => Object.freeze({ ...entry, advances: Object.freeze(entry.advances) })));
const HELD = new Map(), KEPT = new Map(), SHOWN = new Map();

// A set that arrived as its file's bytes (verified against its pin by the plug-in door): admitted and held for this page
// when the catalogue offers it. The set, or null.
export function holdLetterSet(raw) {
	const set = admitLetterSet(raw);
	if (!set || !LETTER_SETS.some(entry => entry.id === set.id)) return null;
	HELD.set(set.id, set); SHOWN.delete(set.id);
	return set;
}
export function letterSetHeld(id) { return HELD.has(id); }

// A capital a drawing's own SVG carries (draw/text.mjs restoreLetters), kept for a set this page does not hold; the first
// kept for a letter stays.
export function keepLetterGlyph(id, letter, path) {
	if (HELD.has(id) || !LETTER_SETS.some(entry => entry.id === id) || letter.length !== 1 || !CAPITALS.includes(letter) || typeof path !== 'string' || path.length > LETTER_LIMITS.glyph || !LETTER_PATH.test(path)) return false;
	if (!KEPT.has(id)) KEPT.set(id, new Map());
	if (!KEPT.get(id).has(letter)) { KEPT.get(id).set(letter, path); SHOWN.delete(id); }
	return true;
}

// The set a text in `letters:<id>` is drawn with: the whole set once held; before that the catalogue's metrics with the
// capitals kept from drawings, every other capital measured by its advance and drawn in the serif; null for an id no set has.
export function letterSet(id) {
	if (HELD.has(id)) return HELD.get(id);
	if (SHOWN.has(id)) return SHOWN.get(id);
	const entry = LETTER_SETS.find(item => item.id === id);
	if (!entry) return null;
	const kept = KEPT.get(id), shown = Object.freeze({ id, name: entry.name, em: 1000, bearing: entry.bearing, space: entry.space,
		glyphs: Object.freeze(Object.fromEntries([...CAPITALS].map((c, i) => [c, Object.freeze([entry.advances[i], kept?.get(c) || null])]))) });
	SHOWN.set(id, shown);
	return shown;
}
